{
  "application": "ppt-generation",
  "case_id": "case-openrouter-stats",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 7,
    "audience": "LLM industry professionals (R&D, product, investment)",
    "tone": "data-forward, engaging, professional"
  },
  "brief": {
    "title": "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter",
    "one_liner": "Based on real usage data from millions of OpenRouter users, this deck reveals the competitive landscape and emerging trends in today's LLM market.",
    "goal": "Help the audience understand which models are most popular in real-world usage, how market share is distributed, which newcomers are rising fast, and what these patterns tell us about industry trends."
  },
  "slides": [
    {
      "id": "title",
      "title": "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter",
      "objective": "Cover slide showcasing the data source (OpenRouter Rankings, latest week of March 2025) and the headline metric: over 26T tokens processed this week."
    },
    {
      "id": "top-models",
      "title": "This Week's Top 10 Models",
      "objective": "Present the 10 most popular models this week using a table or bar chart, including model name, provider, token usage, and week-over-week change. Highlight that Xiaomi's MiMo-V2-Pro tops the list with 3.96T tokens."
    },
    {
      "id": "market-share",
      "title": "Provider Market Share Breakdown",
      "objective": "Use a pie chart or bar chart to show token share by provider. Xiaomi leads at 25.9%, followed by Google at 11.8%, Anthropic at 11.0%, MiniMax at 8.5%, and OpenAI at 7.9%. Note that provider-level market share figures represent share of the total market across all models and apps (including those outside the top 10), so individual provider volumes may differ from summing top-10 model tokens. Emphasize the rise of Chinese providers, whose combined share exceeds 54%."
    },
    {
      "id": "trends",
      "title": "Shifts in the Market Landscape",
      "objective": "Illustrate the current market dynamics and key competitive shifts: (1) Chinese models (Xiaomi, Stepfun, DeepSeek, MiniMax, Zhipu) now hold over 54% combined market share on this international platform; (2) Anthropic's growth has stalled despite maintaining two models in the top 10; (3) Flash/Turbo 'fast and affordable' variants far outpace flagship models in real-world usage. Reference the weekly token usage trend chart showing growth from ~2T to ~26T to underscore the rapidly expanding market."
    },
    {
      "id": "rising-stars",
      "title": "This Week's Rising Stars: Fastest-Growing Models",
      "objective": "Showcase the fastest-growing models: MiniMax M2.7 (+253%), Xiaomi MiMo-V2-Pro (+165%), Cline (+128%). Analyze the drivers behind their surge."
    },
    {
      "id": "app-ecosystem",
      "title": "App Ecosystem: Who's Calling These Models",
      "objective": "Present the top apps by usage: OpenClaw (829B tokens/day), Kilo Code, Claude Code, Cline. Analyze the trend of AI coding assistants becoming the largest usage category."
    },
    {
      "id": "takeaways",
      "title": "Key Insights and Industry Implications",
      "objective": "Summarize 3–4 core takeaways: (1) Chinese models now hold a dominant share in the global market; (2) AI coding agents are the single largest LLM consumption scenario; (3) the model market is highly fragmented with no outright winner; (4) affordable and fast models (Flash/Turbo variants) far outpace flagship models in usage."
    }
  ]
}

arguments.command:
cat << 'EOF' > /app/ppt/generate.js
const pptxgen = require('pptxgenjs');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "0f172a",    // Dark slate - Main text & Cover BG
  secondary: "475569",  // Muted slate - Subtitles/Body
  accent: "2563eb",     // Bright blue - Highlights/Charts
  light: "e2e8f0",      // Light slate - Borders/Alternating rows
  bg: "f8fafc"          // Very light slate - Slide BG
};

// --- Helper Functions ---
function addBadge(slide, number) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText(number.toString().padStart(2, '0'), {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

function addHeader(slide, title) {
  slide.addText(title, {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "left"
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.1, w: 9, h: 0,
    line: { color: theme.accent, width: 2 }
  });
}

// --- Slide 1: Cover ---
let slide1 = pres.addSlide();
slide1.background = { color: theme.primary };
slide1.addText("The 2025 LLM Usage Landscape:\nReal-World Data from OpenRouter", {
  x: 0.5, y: 1.5, w: 9, h: 1.5,
  fontSize: 40, fontFace: "Arial",
  color: "FFFFFF", bold: true, align: "left"
});
slide1.addText("Based on real usage data from millions of OpenRouter users, this deck reveals the competitive landscape and emerging trends in today's LLM market.", {
  x: 0.5, y: 3.2, w: 8, h: 1.0,
  fontSize: 18, fontFace: "Arial",
  color: theme.light, align: "left"
});
slide1.addText("Data Source: OpenRouter Rankings (Latest Week: March 2025)\nHeadline Metric: Over 26T tokens processed this week.", {
  x: 0.5, y: 4.5, w: 8, h: 0.8,
  fontSize: 14, fontFace: "Arial",
  color: theme.accent, bold: true, align: "left"
});

// --- Slide 2: Top 10 Models ---
let slide2 = pres.addSlide();
slide2.background = { color: theme.bg };
addHeader(slide2, "This Week's Top 10 Models");
addBadge(slide2, 2);

// We'll use a table here to show Model, Provider, Tokens, WoW Change
const table2Data = [
  [{text: "Rank", options: {bold: true, color: "FFFFFF"}}, {text: "Model", options: {bold: true, color: "FFFFFF"}}, {text: "Provider", options: {bold: true, color: "FFFFFF"}}, {text: "Weekly Tokens", options: {bold: true, color: "FFFFFF"}}, {text: "WoW Change", options: {bold: true, color: "FFFFFF"}}],
  [1, "MiMo-V2-Pro", "Xiaomi", "3.96T", {text: "+165%", options: {color: "16a34a"}}],
  [2, "Step 3.5 Flash (free)", "Stepfun", "1.49T", "+1%"],
  [3, "MiniMax M2.7", "MiniMax", "1.29T", {text: "+253%", options: {color: "16a34a"}}],
  [4, "DeepSeek V3.2", "DeepSeek", "1.24T", "+9%"],
  [5, "Claude Sonnet 4.6", "Anthropic", "1.04T", "-0%"],
  [6, "Claude Opus 4.6", "Anthropic", "995B", "+2%"],
  [7, "Gemini 3 Flash Preview", "Google", "972B", "+3%"],
  [8, "GLM 5 Turbo", "Zhipu", "968B", "-6%"],
  [9, "MiniMax M2.5", "MiniMax", "909B", {text: "-30%", options: {color: "dc2626"}}],
  [10, "Grok 4.1 Fast", "x-ai", "599B", {text: "+32%", options: {color: "16a34a"}}]
];
slide2.addTable(table2Data, {
  x: 0.5, y: 1.4, w: 9, 
  colW: [0.8, 3.2, 2.0, 1.8, 1.2],
  fill: "FFFFFF",
  border: {pt: 1, color: theme.light},
  rowH: 0.35,
  valign: "middle",
  fontSize: 12,
  fontFace: "Arial",
  align: "center",
  color: theme.primary,
  fillHead: theme.accent
});
slide2.addText("Xiaomi's MiMo-V2-Pro tops the list with a commanding 3.96T tokens processed.", {
  x: 0.5, y: 4.8, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial", color: theme.secondary, italic: true
});

// --- Slide 3: Provider Market Share Breakdown ---
let slide3 = pres.addSlide();
slide3.background = { color: theme.bg };
addHeader(slide3, "Provider Market Share Breakdown");
addBadge(slide3, 3);

const chart3Data = [{
  name: "Market Share",
  labels: ["Xiaomi", "Google", "Anthropic", "MiniMax", "OpenAI", "Stepfun", "DeepSeek", "Zhipu", "x-ai", "Others"],
  values: [25.9, 11.8, 11.0, 8.5, 7.9, 6.8, 6.6, 6.5, 3.9, 11.2]
}];
slide3.addChart(pres.charts.PIE, chart3Data, {
  x: 0.5, y: 1.4, w: 5, h: 3.5,
  dataBorder: {pt: 1, color: "FFFFFF"},
  showLegend: true, legendPos: "r",
  showValue: true, showPercent: true,
  chartColors: ["2563eb", "3b82f6", "60a5fa", "93c5fd", "bfdbfe", "0d9488", "14b8a6", "2dd4bf", "5eead4", "94a3b8"]
});
slide3.addText("Key Takeaways:\n\n• Xiaomi leads decisively at 25.9%\n• Combined Chinese providers (Xiaomi, MiniMax, Stepfun, DeepSeek, Zhipu) exceed 54.3% market share.\n• Note: Provider shares reflect the total market across all models/apps.", {
  x: 5.8, y: 1.4, w: 3.8, h: 3.5,
  fontSize: 14, fontFace: "Arial", color: theme.secondary,
  bullet: true, valign: "top"
});

// --- Slide 4: Shifts in the Market Landscape ---
let slide4 = pres.addSlide();
slide4.background = { color: theme.bg };
addHeader(slide4, "Shifts in the Market Landscape");
addBadge(slide4, 4);

slide4.addText([
  { text: "Chinese Models Break Through Globally", options: { bold: true, color: theme.primary, fontSize: 18, breakLine: true } },
  { text: "Providers like Xiaomi, Stepfun, DeepSeek, MiniMax, and Zhipu now hold over 54% combined market share on OpenRouter, driven by high cost-performance.", options: { fontSize: 14, color: theme.secondary, bullet: true, breakLine: true } },
  { text: "\nAnthropic's Stalled Growth", options: { bold: true, color: theme.primary, fontSize: 18, breakLine: true } },
  { text: "Despite maintaining two top-10 models (Sonnet 4.6 and Opus 4.6), overall growth has stalled amid fierce competition.", options: { fontSize: 14, color: theme.secondary, bullet: true, breakLine: true } },
  { text: "\nRise of 'Fast and Affordable'", options: { bold: true, color: theme.primary, fontSize: 18, breakLine: true } },
  { text: "Flash/Turbo variants far outpace flagship models in real-world usage. Speed and cost matter more than peak performance.", options: { fontSize: 14, color: theme.secondary, bullet: true, breakLine: true } },
  { text: "\nExplosive Overall Market Growth", options: { bold: true, color: theme.primary, fontSize: 18, breakLine: true } },
  { text: "Weekly token usage grew from ~2T to ~26T over the past year, underscoring a rapidly expanding AI market.", options: { fontSize: 14, color: theme.secondary, bullet: true } }
], {
  x: 0.5, y: 1.5, w: 9, h: 3.5,
  valign: "top"
});

// --- Slide 5: This Week's Rising Stars ---
let slide5 = pres.addSlide();
slide5.background = { color: theme.bg };
addHeader(slide5, "This Week's Rising Stars: Fastest-Growing Models");
addBadge(slide5, 5);

const chart5Data = [{
  name: "WoW Growth (%)",
  labels: ["Ampere", "MiniMax M2.7", "MiMo-V2-Pro", "Cline (agent)", "Codex", "Hermes Agent"],
  values: [576, 253, 165, 128, 112, 92]
}];
slide5.addChart(pres.charts.BAR, chart5Data, {
  x: 0.5, y: 1.5, w: 5.5, h: 3.2,
  barDir: "col",
  showValue: true,
  chartColors: [theme.accent],
  valAxisMaxVal: 600,
  dataLabelFormatCode: "0\"%\"",
  catAxisLabelColor: theme.secondary,
  valAxisLabelColor: theme.secondary,
  valAxisLineShow: false
});
slide5.addText("Growth Drivers:\n\n• Ampere: Surging from a smaller baseline.\n• MiniMax & Xiaomi: Combining high capability with aggressive pricing.\n• Cline & Codex: Unprecedented surge in autonomous AI coding tasks.", {
  x: 6.2, y: 1.5, w: 3.3, h: 3.2,
  fontSize: 14, fontFace: "Arial", color: theme.secondary,
  bullet: true, valign: "top"
});

// --- Slide 6: App Ecosystem: Who's Calling These Models ---
let slide6 = pres.addSlide();
slide6.background = { color: theme.bg };
addHeader(slide6, "App Ecosystem: Who's Calling These Models");
addBadge(slide6, 6);

const chart6Data = [{
  name: "Daily Tokens (B)",
  labels: ["OpenClaw", "Kilo Code", "Claude Code", "Cline", "Janitor AI", "ISEKAI ZERO", "Descript", "Hermes Agent", "Roo Code", "Scripty"],
  values: [829, 271, 78, 69.1, 29.2, 28.8, 27, 19.2, 11.8, 9.95]
}];
slide6.addChart(pres.charts.BAR, chart6Data, {
  x: 0.5, y: 1.5, w: 9, h: 2.2,
  barDir: "col",
  showValue: true,
  chartColors: ["14b8a6"],
  catAxisLabelColor: theme.secondary,
  valAxisLabelColor: theme.secondary,
  valAxisLineShow: false
});

slide6.addText("Analysis:\n• AI coding assistants are the largest usage category (Top 4: OpenClaw, Kilo Code, Claude Code, Cline).\n• OpenClaw consumes 829B tokens/day — nearly 3× the second-place app.\n• Entertainment/roleplay (Janitor AI, ISEKAI ZERO) remains a notable segment.", {
  x: 0.5, y: 4.0, w: 9, h: 1.2,
  fontSize: 14, fontFace: "Arial", color: theme.secondary,
  bullet: true, valign: "top"
});

// --- Slide 7: Key Insights and Industry Implications ---
let slide7 = pres.addSlide();
slide7.background = { color: theme.bg };
addHeader(slide7, "Key Insights and Industry Implications");
addBadge(slide7, 7);

slide7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 0.5, y: 1.5, w: 4.2, h: 1.6,
  fill: { color: "FFFFFF" },
  line: { color: theme.light, pt: 1 },
  rectRadius: 0.1
});
slide7.addText("1. Global Shift to Chinese Models", {
  x: 0.6, y: 1.6, w: 4.0, h: 0.4, fontSize: 16, bold: true, color: theme.primary
});
slide7.addText("Chinese models now hold a dominant share (>54%) in the global market driven by compelling cost-to-performance ratios.", {
  x: 0.6, y: 2.0, w: 4.0, h: 1.0, fontSize: 13, color: theme.secondary, valign: "top"
});

slide7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 5.0, y: 1.5, w: 4.2, h: 1.6,
  fill: { color: "FFFFFF" },
  line: { color: theme.light, pt: 1 },
  rectRadius: 0.1
});
slide7.addText("2. The Rise of Coding Agents", {
  x: 5.1, y: 1.6, w: 4.0, h: 0.4, fontSize: 16, bold: true, color: theme.primary
});
slide7.addText("AI coding agents represent the single largest LLM consumption scenario today, driving massive token volume.", {
  x: 5.1, y: 2.0, w: 4.0, h: 1.0, fontSize: 13, color: theme.secondary, valign: "top"
});

slide7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 0.5, y: 3.4, w: 4.2, h: 1.6,
  fill: { color: "FFFFFF" },
  line: { color: theme.light, pt: 1 },
  rectRadius: 0.1
});
slide7.addText("3. Highly Fragmented Market", {
  x: 0.6, y: 3.5, w: 4.0, h: 0.4, fontSize: 16, bold: true, color: theme.primary
});
slide7.addText("No single model or provider monopolizes usage. The top 10 spans 8 providers, indicating fierce, ongoing competition.", {
  x: 0.6, y: 3.9, w: 4.0, h: 1.0, fontSize: 13, color: theme.secondary, valign: "top"
});

slide7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 5.0, y: 3.4, w: 4.2, h: 1.6,
  fill: { color: "FFFFFF" },
  line: { color: theme.light, pt: 1 },
  rectRadius: 0.1
});
slide7.addText("4. Speed & Cost Over Peak Performance", {
  x: 5.1, y: 3.5, w: 4.0, h: 0.4, fontSize: 16, bold: true, color: theme.primary
});
slide7.addText("Affordable and fast models (Flash/Turbo variants) are far outpacing flagship models in real-world application usage.", {
  x: 5.1, y: 3.9, w: 4.0, h: 1.0, fontSize: 13, color: theme.secondary, valign: "top"
});

// Save presentation
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(fileName => {
    console.log(`Created file: ${fileName}`);
  })
  .catch(err => {
    console.error(err);
  });
EOF

